      `PERSON_HELD sheet=${sheet} by=uma name=Ada from=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=4.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=40.00 due-total=8.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=cap value=2.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=2.00 overdue-total=0.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=20.00 due-total=2.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=40.00 due-total=4.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=cap value=`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=4.00 overdue-total=0.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=20.00 due-total=4.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=40.00 due-total=8.00 overdue-total=0.00`,
      `ALERT sheet=${sheet} by=uma name=Ada due-total=4.00`,
      `ALERT sheet=${sheet} by=uma name=Ben due-total=4.00`,
